auto const& p = rt.point(c, 0);
auto const& q = rt.point(c, 1);
auto const& r = rt.point(c, 2);
auto const& s = rt.point(c, 3);

auto const& wp = rt.weighted_point(c, 0);
auto const& wq = rt.weighted_point(c, 1);
auto const& wr = rt.weighted_point(c, 2);
auto const& ws = rt.weighted_point(c, 3);

std::array<std::array<double, 4>, 4> lifted_points;
lifted_points[0] = {wp.x(), wp.y(), wp.z(), wp.weight() + time};
lifted_points[1] = {wq.x(), wq.y(), wq.z(), wq.weight() + time};
lifted_points[2] = {wr.x(), wr.y(), wr.z(), wr.weight() + time};
lifted_points[3] = {ws.x(), ws.y(), ws.z(), ws.weight() + time};

double det = lifted_points[0][0] * (lifted_points[1][1] * (lifted_points[2][2] * lifted_points[3][3] - lifted_points[2][3] * lifted_points[3][2]) -
                                   lifted_points[1][2] * (lifted_points[2][1] * lifted_points[3][3] - lifted_points[2][3] * lifted_points[3][1]) +
                                   lifted_points[1][3] * (lifted_points[2][1] * lifted_points[3][2] - lifted_points[2][2] * lifted_points[3][1])) -
             lifted_points[0][1] * (lifted_points[1][0] * (lifted_points[2][2] * lifted_points[3][3] - lifted_points[2][3] * lifted_points[3][2]) -
                                   lifted_points[1][2] * (lifted_points[2][0] * lifted_points[3][3] - lifted_points[2][3] * lifted_points[3][0]) +
                                   lifted_points[1][3] * (lifted_points[2][0] * lifted_points[3][2] - lifted_points[2][2] * lifted_points[3][0])) +
             lifted_points[0][2] * (lifted_points[1][0] * (lifted_points[2][1] * lifted_points[3][3] - lifted_points[2][3] * lifted_points[3][1]) -
                                   lifted_points[1][1] * (lifted_points[2][0] * lifted_points[3][3] - lifted_points[2][3] * lifted_points[3][0]) +
                                   lifted_points[1][3] * (lifted_points[2][0] * lifted_points[3][1] - lifted_points[2][1] * lifted_points[3][0])) -
             lifted_points[0][3] * (lifted_points[1][0] * (lifted_points[2][1] * lifted_points[3][2] - lifted_points[2][2] * lifted_points[3][1]) -
                                   lifted_points[1][1] * (lifted_points[2][0] * lifted_points[3][2] - lifted_points[2][2] * lifted_points[3][0]) +
                                   lifted_points[1][2] * (lifted_points[2][0] * lifted_points[3][1] - lifted_points[2][1] * lifted_points[3][0]));

if (std::abs(det) < 1e-12) {
    return Vector(0.0, 0.0, 0.0);
}

std::array<double, 3> velocity = {0.0, 0.0, 0.0};
for (int i = 0; i < 3; ++i) {
    std::array<std::array<double, 4>, 4> minor;
    for (int j = 0; j < 4; ++j) {
        for (int k = 0; k < 4; ++k) {
            if (k == 3) {
                minor[j][k] = lifted_points[j][i];
            } else {
                minor[j][k] = lifted_points[j][k];
            }
        }
    }
    double minor_det = minor[0][0] * (minor[1][1] * (minor[2][2] * minor[3][3] - minor[2][3] * minor[3][2]) -
                                      minor[1][2] * (minor[2][1] * minor[3][3] - minor[2][3] * minor[3][1]) +
                                      minor[1][3] * (minor[2][1] * minor[3][2] - minor[2][2] * minor[3][1])) -
                       minor[0][1] * (minor[1][0] * (minor[2][2] * minor[3][3] - minor[2][3] * minor[3][2]) -
                                      minor[1][2] * (minor[2][0] * minor[3][3] - minor[2][3] * minor[3][0]) +
                                      minor[1][3] * (minor[2][0] * minor[3][2] - minor[2][2] * minor[3][0])) +
                       minor[0][2] * (minor[1][0] * (minor[2][1] * minor[3][3] - minor[2][3] * minor[3][1]) -
                                      minor[1][1] * (minor[2][0] * minor[3][3] - minor[2][3] * minor[3][0]) +
                                      minor[1][3] * (minor[2][0] * minor[3][1] - minor[2][1] * minor[3][0])) -
                       minor[0][3] * (minor[1][0] * (minor[2][1] * minor[3][2] - minor[2][2] * minor[3][1]) -
                                      minor[1][1] * (minor[2][0] * minor[3][2] - minor[2][2] * minor[3][0]) +
                                      minor[1][2] * (minor[2][0] * minor[3][1] - minor[2][1] * minor[3][0]));
    velocity[i] = minor_det / det;
}

return Vector(velocity[0], velocity[1], velocity[2]);

